from schema import mcq

mcq(10,1,'بررسی تجربی و متغیرها','در بررسی اثر شوری بر جوانه‌زنی، دو ظرف بذر هم‌نوع با دما، نور و آب یکسان آماده شده‌اند؛ فقط به یکی نمک افزوده می‌شود. برای ارزیابی نتیجه، کدام داده مستقیماً مناسب‌تر است؟',[
('نظر افراد دربارهٔ زیبایی گیاهچه‌ها','زیبایی داوری شخصی است و شاخص مستقیم جوانه‌زنی نیست.'),
('درصد بذرهای جوانه‌زده در هر ظرف پس از زمان یکسان','درصد جوانه‌زنی در زمان برابر متغیر پاسخ را کمی می‌کند و مقایسهٔ دو شرایط را ممکن می‌سازد.'),
('رنگ ظرف‌ها بدون شمارش بذرهای جوانه‌زده','رنگ ظرف به‌تنهایی اطلاعاتی از جوانه‌زنی نمی‌دهد.'),
('فقط تعداد بذرهای کاشته‌شده پیش از آزمایش','تعداد اولیه برای محاسبهٔ درصد لازم است، اما به‌تنهایی پیامد شوری را نشان نمی‌دهد.')],1,'متغیر پاسخ را با شرایط ثابت یا مقدار اولیه اشتباه نگیریم.','easy')
mcq(10,1,'نگرش سامانه‌ای','پژوهشگری برای توضیح افزایش دمای بدن هنگام ورزش، فقط یاختهٔ ماهیچه را بررسی می‌کند. کدام بررسی، دیدگاه سامانه‌ای او را کامل‌تر می‌کند؟',[
('بررسی هم‌زمان فعالیت ماهیچه، گردش خون و تنظیم دفع گرما','دما حاصل برهم‌کنش تولید و دفع گرما در چند بخش بدن است؛ بررسی ارتباط دستگاه‌ها نگرش سامانه‌ای دارد.'),
('حذف نقش پوست چون جزو ماهیچه نیست','پوست در دفع گرما نقش دارد و کنارگذاشتن آن ارتباط سامانه‌ها را نادیده می‌گیرد.'),
('یکسان فرض‌کردن فعالیت همهٔ بافت‌های بدن','یاخته‌ها و بافت‌ها نقش‌ها و میزان فعالیت یکسانی ندارند.'),
('نتیجه‌گیری دربارهٔ کل بدن از یک واکنش جداشده بدون بررسی ارتباط‌ها','ویژگی سامانه را نمی‌توان همواره از یک جزء جداشده و بدون ارتباط‌ها توضیح داد.')],0,'در سامانهٔ زنده، ارتباط اجزا بخشی از توضیح پدیده است.')
mcq(10,1,'سطوح سازمان‌یابی','در یک برکه، کاهش گیاهان آبزی با کاهش جمعیت ماهی‌ها همراه شده است. کدام پرسش به سطح بوم‌سازگان مربوط است؟',[
('چند فام‌تن در یاختهٔ یک ماهی وجود دارد؟','فام‌تن به سطح یاخته و مولکول‌های اطلاعاتی مربوط است.'),
('بافت پوششی آبشش چه شکلی دارد؟','این پرسش ساختار بافت یک جاندار را بررسی می‌کند.'),
('نور و اکسیژن با جانداران چه ارتباطی دارند؟','بوم‌سازگان شامل جانداران، عوامل غیرزنده و ارتباط آن‌هاست؛ نور و اکسیژن از عوامل غیرزنده‌اند.'),
('یک ماهی چگونه بالهٔ خود را حرکت می‌دهد؟','این پرسش عمدتاً کارکرد اندام در یک فرد را بررسی می‌کند.')],2,'جمعیت‌ها همراه عوامل غیرزنده، سطح بوم‌سازگان را می‌سازند.')
mcq(10,1,'هم‌ایستایی','پس از گرم‌شدن محیط، تعریق و افزایش جریان خون پوست به محدودشدن افزایش دمای مرکزی کمک می‌کنند. کدام برداشت درست است؟',[
('هم‌ایستایی یعنی هیچ کمیت درونی حتی اندکی تغییر نکند','هم‌ایستایی ثبات نسبی در محدودهٔ مناسب است، نه نبود هرگونه نوسان.'),
('تعریق نشان می‌دهد بدن دیگر هیچ تنظیمی ندارد','تعریق خود یک پاسخ تنظیمی در دفع گرماست.'),
('دمای بدن باید بدون پاسخ یاخته‌ها دقیقاً برابر محیط شود','بدن با پاسخ‌های تنظیمی می‌تواند دمای درونی را در محدودهٔ مناسب حفظ کند.'),
('پاسخ دستگاه‌ها می‌تواند تغییر محیط را تا حدی جبران کند','هم‌ایستایی با فعالیت هماهنگ بخش‌های بدن و جبران تغییرات، ثبات نسبی محیط درونی را حفظ می‌کند.')],3,'ثبات نسبی را با ثابت‌بودن مطلق یکی ندانیم.')

mcq(10,2,'جذب روده‌ای','اگر سطح پرزهای رودهٔ باریک آسیب ببیند ولی آنزیم‌های گوارشی به مقدار معمول ترشح شوند، کدام پیامد مستقیم‌تر است؟',[
('توقف قطعی شکستن نشاسته در دهان','آسیب پرز روده مستقیماً ترشح آمیلاز بزاق را متوقف نمی‌کند.'),
('کاهش سطح تماس برای جذب مواد گوارش‌یافته','پرزها سطح جذب را افزایش می‌دهند؛ آسیب آن‌ها حتی با گوارش شیمیایی طبیعی می‌تواند جذب را کاهش دهد.'),
('افزایش جذب به علت کوتاه‌ترشدن مسیر طولی روده','آسیب پرزها سطح جذب را کم می‌کند؛ کوتاه‌شدن پرز به معنی عبور آسان‌تر مواد از پوشش نیست.'),
('کاهش جذب فقط به‌علت نرسیدن آنزیم به معده','فرض سؤال ترشح کافی آنزیم است و آسیب پرز در روده، مشکل سطح جذب ایجاد می‌کند.')],1,'گوارش شیمیایی و جذب دو فرایند جداگانه‌اند.','medium')
mcq(10,2,'صفرا و چربی','دو لوله دارای مقدار مساوی چربی و لیپاز در شرایط مناسب‌اند. به یکی صفرا افزوده می‌شود. چرا ریزشدن قطره‌های چربی می‌تواند سرعت گوارش را بیشتر کند؟',[
('صفرا پیوند پپتیدی چربی را می‌شکند','چربی پیوند پپتیدی ندارد و صفرا نیز آنزیم گوارشی نیست.'),
('صفرا مقدار لیپاز افزوده‌شده به لوله را بیشتر می‌کند','در آزمایش مقدار لیپاز برابر نگه داشته شده است؛ تفاوت از دسترسی آنزیم به سطح چربی می‌آید.'),
('سطح تماس چربی با لیپاز افزایش می‌یابد','پخش چربی در قطره‌های کوچک‌تر سطح تماس را افزایش می‌دهد و دسترسی لیپاز به مادهٔ غذایی بیشتر می‌شود.'),
('با افزودن صفرا، دیگر هیچ آنزیمی لازم نیست','صفرا پخش چربی را تسهیل می‌کند، اما شکستن شیمیایی به آنزیم نیاز دارد.')],2,'نقش فیزیکی صفرا را با عمل آنزیمی لیپاز اشتباه نگیریم.')
mcq(10,2,'حرکت لولهٔ گوارش','هنگام بلع، لقمه با وجود تغییر وضعیت بدن به‌سوی معده پیش می‌رود. کدام سازوکار در این حرکت نقش اصلی دارد؟',[
('انقباض هماهنگ ماهیچه‌های دیوارهٔ مری به‌صورت حرکات کرمی','حرکات کرمی با انقباض هماهنگ دیواره، محتویات لولهٔ گوارش را جلو می‌برند و فقط به وزن لقمه وابسته نیستند.'),
('اثر گرانش به‌تنهایی و بدون فعالیت دیوارهٔ مری','پیش‌رانی لقمه فقط به وزن آن متکی نیست و با حرکت کرمی دیواره در وضعیت‌های مختلف ادامه می‌یابد.'),
('شل‌ماندن هم‌زمان ماهیچه‌های تمام طول مری','پیش‌رانی به الگوی هماهنگ انقباض و شل‌شدن نیاز دارد؛ شل‌ماندن همهٔ مسیر نیروی پیش‌ران نمی‌سازد.'),
('انقباض یکسان و ثابت همهٔ بخش‌های مری بدون موج حرکتی','حرکت کرمی پیشروی هماهنگ تغییر انقباض در طول مسیر است، نه انقباض ثابت همهٔ قسمت‌ها.')],0,'نیروی پیش‌ران لقمه را فقط به گرانش نسبت ندهیم.','easy')
mcq(10,2,'جذب چربی و قند','پس از جذب یک وعدهٔ غذایی، کدام مقایسه دربارهٔ بیشتر قندهای ساده و فرآورده‌های بسته‌بندی‌شدهٔ چربی در پرز درست است؟',[
('هر دو گروه ابتدا فقط وارد رگ لنفی پرز می‌شوند','قندهای ساده عمدتاً وارد مویرگ‌های خونی پرز می‌شوند.'),
('قند ساده وارد مویرگ خونی و بسته‌های چربی عمدتاً وارد رگ لنفی می‌شوند','در پرز، مسیر اولیهٔ جذب بیشتر قندهای ساده خونی است؛ بسته‌های لیپیدی عمدتاً به رگ لنفی راه می‌یابند.'),
('قند ساده بدون عبور از یاختهٔ پوششی از دیوارهٔ روده خارج می‌شود','در جذب معمول، مواد از سد پوششی روده عبور می‌کنند.'),
('بسته‌های چربی ابتدا وارد مویرگ خونی و قندها عمدتاً وارد رگ لنفی می‌شوند','این گزینه دو مسیر اصلی را وارونه کرده است؛ قندها عمدتاً خونی و بسته‌های چربی عمدتاً لنفی‌اند.')],1,'ورود به محیط درونی برای همهٔ مواد مسیر اولیهٔ یکسان ندارد.','hard')

mcq(10,3,'انتشار گازها','در شکل، فشار نسبی اکسیژن در دو ناحیهٔ فرضی A و B نشان داده شده است. اگر ضخامت سطح تبادل بین آن‌ها بیشتر شود ولی اختلاف فشار نسبی و سطح تماس ثابت بماند، کدام انتظار مناسب‌تر است؟',[
('حرکت خالص سریع‌تر از A به B','با ثابت‌بودن سایر عوامل، افزایش ضخامت مسیر انتشار را طولانی‌تر و تبادل را کندتر می‌کند.'),
('تغییر جهت حرکت خالص به B به A','ضخامت بیشتر به‌تنهایی جهت اختلاف فشار نسبی را عوض نمی‌کند.'),
('حرکت خالص کندتر از A به B','در A فشار نسبی بیشتر است، پس جهت خالص به B می‌ماند؛ ضخامت بیشتر، با ثابت‌بودن عوامل دیگر، سرعت انتشار را کم می‌کند.'),
('برابرشدن فوری فشار دو ناحیه به علت افزایش ضخامت','ضخامت بیشتر باعث تعادل فوری نمی‌شود؛ در فرض سؤال اختلاف نیز ثابت نگه داشته شده است.')],2,'عوامل مؤثر بر سرعت انتشار را از عامل تعیین جهت آن جدا کنیم.',image='diagrams/oxygen.png')
mcq(10,3,'تهویهٔ ششی','در آغاز دم آرام، حجم قفسهٔ سینه افزایش یافته است. با فرض بازبودن راه‌های هوایی، کدام زنجیره درست است؟',[
('کاهش حجم شش ← کاهش فشار هوای شش ← ورود هوا','در دم حجم شش همراه قفسهٔ سینه افزایش می‌یابد، نه کاهش.'),
('افزایش فشار هوای شش نسبت به بیرون ← ورود هوا','هوا از فشار بیشتر به کمتر می‌رود؛ افزایش فشار درون شش به خروج کمک می‌کند.'),
('انقباض دیافراگم ← کاهش حجم قفسهٔ سینه ← خروج هوا','انقباض دیافراگم آن را مسطح‌تر می‌کند و حجم قفسهٔ سینه را افزایش می‌دهد.'),
('افزایش حجم شش ← افت فشار هوای آن نسبت به بیرون ← ورود هوا','افزایش حجم سبب افت فشار نسبت به بیرون می‌شود و هوا در امتداد اختلاف فشار وارد شش می‌شود.')],3,'اثر افزایش حجم بر فشار را وارونه نکنیم.')
mcq(10,3,'تبادل در آبشش','در دو بخش X و Y از سطح آبشش، فشار نسبی اکسیژنِ آب و خون مقابل آن به‌ترتیب X:۷۰ و ۴۰، Y:۴۵ و ۲۰ واحد فرضی است. با ثابت‌بودن این مقادیر، کدام استدلال درست است؟',[
('در هر دو بخش اکسیژن خالص از آب وارد خون می‌شود','در هر بخش باید آب و خون روبه‌روی همان بخش را مقایسه کرد؛ ۷۰>۴۰ و ۴۵>۲۰، پس جهت خالص در هر دو آب به خون است.'),
('در Y اکسیژن از خون به آب می‌رود، چون عدد آب از X کمتر است','کمترشدن اکسیژن آب نسبت به نقطهٔ دیگر کافی نیست؛ آب Y هنوز از خون مقابلش اکسیژن بیشتری دارد.'),
('از این داده‌ها، جهت انتشار CO2 هم دقیقاً همان است','برای CO2 باید فشار نسبی خود آن گاز در دو سوی سطح معلوم باشد؛ اختلاف O2 جهت CO2 را تعیین نمی‌کند.'),
('در X تبادل ممکن نیست، چون دو مقدار اکسیژن برابر نیستند','نابرابری فشار نسبی زمینهٔ انتشار خالص است؛ برابرشدن مقادیر آن را به صفر نزدیک می‌کند.')],0,'مقادیر دو سوی یک نقطه را مقایسه کنیم، نه آبِ دو نقطهٔ متفاوت را.')
mcq(10,3,'تنفس نایی حشرات','با مسدودشدن بسیاری از روزنه‌های تنفسی یک حشره، رساندن اکسیژن به بافت‌ها مختل می‌شود. چرا افزایش گردش مایع بدن به‌تنهایی مشکل را جبران نمی‌کند؟',[
('زیرا اکسیژن باید ابتدا از شش حشره به خون وارد شود','حشره دستگاه نایی دارد؛ شش و انتقال اصلی با خون الگوی معمول آن نیست.'),
('زیرا رساندن گاز عمدتاً با نای‌هاست، نه گردش مایع بدن','در حشرات، دستگاه نایی اکسیژن را مستقیم به نزدیکی بافت‌ها می‌رساند؛ بسته‌شدن ورودی هوا با افزایش گردش مایع جبران نمی‌شود.'),
('زیرا تمام اکسیژن ابتدا در روده جذب و سپس وارد مایع بدن می‌شود','راه اصلی ورود اکسیژن در دستگاه نایی از روزنه‌ها و مجاری تنفسی است، نه جذب گوارشی.'),
('زیرا روزنه‌ها فقط راه خروج CO2 هستند و در ورود اکسیژن نقشی ندارند','روزنه‌های تنفسی راه ارتباط دستگاه نایی با هوا هستند و بسته‌شدن آن‌ها ورود اکسیژن را نیز محدود می‌کند.')],1,'الگوی رساندن اکسیژن مهره‌داران را به حشرات تعمیم ندهیم.')

mcq(10,4,'دریچه‌ها و فشار قلب','در بخشی از چرخهٔ قلب، فشار بطن چپ از دهلیز چپ بیشتر ولی هنوز از آئورت کمتر است. دریچه‌های دولختی و سینی آئورتی به‌ترتیب چه وضعی دارند؟',[
('باز و باز','فشار بیشتر بطن نسبت به دهلیز دولختی را می‌بندد و فشار کمتر از آئورت سینی را باز نمی‌کند.'),
('باز و بسته','دولختی با بیشترشدن فشار بطن از دهلیز بسته می‌شود.'),
('بسته و باز','برای بازشدن سینی آئورتی، فشار بطن باید از فشار آئورت بیشتر شود.'),
('بسته و بسته','بیشتربودن فشار بطن از دهلیز دریچهٔ دولختی را می‌بندد؛ تا پیش از غلبه بر فشار آئورت، سینی نیز بسته می‌ماند.')],3,'بازشدن دو نوع دریچه به دو مقایسهٔ فشار جداگانه وابسته است.','hard')
mcq(10,4,'دو گردش خون','در شکل طرح گردش خون، A دهلیز راست، B بطن راست، C دهلیز چپ و D بطن چپ است. کدام مسیر از B تا آغاز گردش عمومی درست است؟',[
('B → شش‌ها → D → C → بدن','خون بازگشته از شش ابتدا به دهلیز چپ C وارد می‌شود، نه بطن چپ D؛ خروج عمومی از D است.'),
('B → شش‌ها → C → D → بدن','خون از بطن راست به شش‌ها، سپس دهلیز و بطن چپ می‌رود و از بطن چپ وارد گردش عمومی می‌شود.'),
('B → بدن → D → شش‌ها','بطن راست خون را به شش‌ها می‌فرستد، نه مستقیماً به بدن؛ بازگشت ششی نیز ابتدا به دهلیز چپ است.'),
('B → A → شش‌ها → D','خروج طبیعی خون از بطن راست به سرخرگ ششی است، نه بازگشت به دهلیز راست.')],1,'راست و چپ قلب دو مدار متوالی را به هم پیوند می‌دهند.',image='diagrams/circulation.png')
mcq(10,4,'ساختار رگ‌ها','در مقایسهٔ سرخرگ و سیاهرگ هم‌اندازه در گردش عمومی، چرا دیوارهٔ سرخرگ معمولاً بخش ماهیچه‌ای و کشسان ضخیم‌تری دارد؟',[
('زیرا همهٔ سرخرگ‌ها خون بی‌اکسیژن دارند','اکسیژن خون معیار نام‌گذاری سرخرگ نیست؛ بیشتر سرخرگ‌های عمومی خون اکسیژن‌دار دارند.'),
('زیرا سرعت انتشار مواد فقط با ضخیم‌شدن دیواره بیشتر می‌شود','دیوارهٔ نازک مویرگ برای تبادل مناسب است؛ ضخامت سرخرگ برای افزایش انتشار نیست.'),
('زیرا خون را با فشار بالاتری از قلب دریافت می‌کند','بخش کشسان و ماهیچه‌ای سرخرگ با تحمل و تنظیم جریان خون پرفشار ارتباط دارد.'),
('زیرا فشار خون در سیاهرگ‌های هم‌اندازه معمولاً بیشتر است','در مقایسهٔ معمول گردش عمومی، سرخرگ خون پرفشارتر را دریافت می‌کند؛ این گزینه رابطهٔ فشار را وارونه کرده است.')],2,'دیوارهٔ ضخیم‌تر را با سطح تبادل مؤثرتر یکی ندانیم.')
mcq(10,4,'مایع میان‌بافتی و لنف','اگر بازگشت لنف یک ناحیه کاهش یابد، با وجود ادامهٔ ورود بخشی از مایع از مویرگ‌ها به بافت، کدام پیامد محتمل‌تر است؟',[
('تجمع مایع در فضای میان یاخته‌ها و تورم آن ناحیه','رگ‌های لنفی بخشی از مایع میان‌بافتی را به گردش برمی‌گردانند؛ اختلال بازگشت می‌تواند موجب تجمع مایع شود.'),
('کاهش مایع میان‌بافتی چون رگ لنفی مسدود آن را سریع‌تر تخلیه می‌کند','کاهش تخلیه، خروج مایع را بیشتر نمی‌کند و می‌تواند به انباشت بینجامد.'),
('جبران الزامی و کامل تمام مایع اضافی توسط بازگشت مویرگی','بازگشت مویرگی الزاماً جای تخلیهٔ لنفی را کاملاً جبران نمی‌کند؛ فرض ادامهٔ ورود و کاهش خروج زمینهٔ تورم است.'),
('افزایش خروج مایع از بافت فقط به علت کاهش جریان لنف','جریان لنف خود یکی از راه‌های خروج است؛ کم‌شدن آن به‌تنهایی خروج مایع از بافت را افزایش نمی‌دهد.')],0,'بازگشت مایع میان‌بافتی فقط از راه مویرگ خونی انجام نمی‌شود.')

mcq(10,5,'تراوش و بازجذب','ماده‌ای کوچک در خون وجود دارد، از صافی کلافک عبور می‌کند و در فرد سالم از ادرار نهایی تقریباً حذف می‌شود. دربارهٔ قند گلوکز، کدام توضیح مناسب است؟',[
('گلوکز وارد نفرون نمی‌شود چون مولکول پروتئینی بزرگی است','گلوکز مولکول کوچکی است و پروتئین نیست؛ می‌تواند وارد مایع تراوش‌شده شود.'),
('گلوکز پس از تراوش، در مسیر لولهٔ نفرون به خون بازجذب می‌شود','در شرایط طبیعی گلوکز تراوش‌شده تقریباً به‌طور کامل بازجذب می‌شود؛ نبود آن در ادرار به معنی نبود تراوش نیست.'),
('گلوکز پس از رسیدن به مثانه از راه میزنای به خون بازمی‌گردد','بازجذب اصلی گلوکز در نفرون انجام می‌شود؛ میزنای مسیر بازگشت انتخابی گلوکز به خون نیست.'),
('هر ماده‌ای که تراوش شود الزاماً به همان مقدار دفع می‌شود','بازجذب و ترشح ترکیب مایع را تغییر می‌دهند؛ مقدار تراوش و دفع لزوماً برابر نیست.')],1,'نبود ماده در ادرار را با عبورنکردن از صافی یکی ندانیم.')
mcq(10,5,'کبد و دفع نیتروژن','در بیماری، توان کبد برای تبدیل آمونیاک به اوره کاهش یافته، ولی خون‌رسانی و کار کلیه فعلاً طبیعی است. کدام برداشت درست‌تر است؟',[
('کلیهٔ سالم ثابت می‌کند تبدیل آمونیاک به اوره نیز حتماً طبیعی است','ساخت اوره عمدتاً در کبد و دفع آن از خون در کلیه انجام می‌شود؛ سلامت یکی سلامت دیگری را ثابت نمی‌کند.'),
('چون اوره در ادرار هست، محل اصلی ساخت آن مثانه است','وجود ماده در ادرار محل ساخت آن را نشان نمی‌دهد؛ مثانه عمدتاً محل ذخیرهٔ ادرار است.'),
('اختلال ساخت اوره با اختلال دفع کلیوی آن یکسان نیست','کبد مادهٔ نیتروژن‌دار را به شکل کم‌سم‌تری تبدیل می‌کند و کلیه در دفع نقش دارد؛ اختلال تبدیل می‌تواند با وجود کار طبیعی کلیه رخ دهد.'),
('کاهش ساخت اوره الزاماً به معنی کاهش تولید آمونیاک در همهٔ بافت‌هاست','فرض سؤال کاهش توان تبدیل در کبد است؛ از آن نمی‌توان کاهش تولید آمونیاک را در همهٔ بافت‌ها نتیجه گرفت.')],2,'محل ساخت مادهٔ دفعی را از محل جداکردن آن از خون تفکیک کنیم.')
mcq(10,5,'دفع نیتروژن','در جانوری که دسترسی پیوسته به آب فراوان ندارد، دفع اوریک‌اسید کم‌حل‌شونده نسبت به دفع آمونیاک چه مزیت عمده‌ای دارد؟',[
('امکان دفع مواد نیتروژن‌دار با آب کمتر','اوریک‌اسید کم‌محلول را می‌توان با آب کمتری دفع کرد؛ آمونیاک برای دفع ایمن به رقیق‌شدن بیشتری نیاز دارد.'),
('افزایش نیاز به رقیق‌کردن مادهٔ دفعی با آب فراوان','دفع اوریک‌اسیدِ کم‌حل‌شونده نیاز کمتری به آب دارد؛ این گزینه جهت مزیت را وارونه می‌کند.'),
('افزایش دفع آمونیاکِ حل‌شده بدون تغییر مصرف آب','مزیتِ مورد سؤال تغییر شکل مادهٔ نیتروژن‌دار به اوریک‌اسید است، نه افزایش آمونیاک محلول.'),
('جلوگیری از هرگونه هزینهٔ انرژی برای ساخت مادهٔ دفعی','ساخت اوریک‌اسید هزینهٔ انرژی دارد؛ مزیت آن صرفه‌جویی در آب است.')],0,'صرفه‌جویی در آب را با کم‌هزینه‌بودن ساخت مادهٔ دفعی اشتباه نگیریم.')
mcq(10,5,'بازجذب و ترشح','در بخشی از نفرون، مادهٔ X از خون مویرگ به درون لوله و آب از لوله به خون می‌رود. نام این دو جابه‌جایی به‌ترتیب چیست؟',[
('بازجذب و ترشح','جهت X خون به لوله است و ترشح نام دارد؛ جهت آب لوله به خون بازجذب است.'),
('تراوش و تراوش','تراوش به عبور مایع از کلافک به کپسول گفته می‌شود؛ این دو جابه‌جایی لوله‌ای آن نیستند.'),
('بازجذب و تراوش','بازجذب جهت لوله به خون دارد، در حالی که X خلاف آن حرکت کرده است.'),
('ترشح و بازجذب','ترشح ورود ماده از خون به لوله و بازجذب بازگشت ماده از لوله به خون است.')],3,'نام فرایند را از جهت عبور نسبت به لوله تعیین کنیم.','easy')

mcq(10,6,'تورژسانس و دیواره','یاختهٔ گیاهی زنده‌ای با دیوارهٔ سالم در آب خالص قرار می‌گیرد و متورم می‌شود. چرا معمولاً مانند یاختهٔ جانوری نمی‌ترکد؟',[
('دیواره کاملاً مانع ورود هر مولکول آب می‌شود','آب می‌تواند وارد یاخته شود؛ دیواره سد نفوذناپذیر آب نیست.'),
('فشار دیواره در برابر افزایش حجم، ورود خالص بیشتر آب را محدود می‌کند','ورود آب فشار تورژسانس ایجاد می‌کند و مقاومت دیواره افزایش حجم را محدود می‌سازد.'),
('غشای یاختهٔ گیاهی فاقد خاصیت انتخاب‌پذیری است','غشای یاختهٔ گیاهی نیز تراوایی انتخابی دارد.'),
('کاهش غلظت محلول درون یاخته، به‌تنهایی هر ورود بعدی آب را ناممکن می‌کند','رقیق‌شدن می‌تواند اختلاف را کم کند، اما نقش مقاومت دیواره و فشار تورژسانس را حذف نمی‌کند و ورود را به‌طور مطلق ناممکن نمی‌سازد.')],1,'دیواره از افزایش نامحدود حجم جلوگیری می‌کند، نه از هر ورود آب.')
mcq(10,6,'بافت‌های نگهدارنده','بافتی در ساقهٔ جوان باید همراه رشد طولی اندام کشیده شود و هم‌زمان تکیه‌گاه آن باشد. کدام ویژگی با کلانشیم سازگارتر است؟',[
('یاخته‌های مرده با دیوارهٔ پسین کاملاً چوبی','این ویژگی بیشتر با اسکلرانشیم سازگار است؛ کلانشیم در حالت بالغ زنده است.'),
('نبود دیوارهٔ یاخته‌ای در تمام یاخته‌های بافت','یاخته‌های کلانشیم دیواره دارند و ضخیم‌شدن دیواره به نگهداری کمک می‌کند.'),
('یاخته‌های زنده با دیوارهٔ نخستین دارای ضخامت نامساوی','کلانشیم با یاخته‌های زنده و دیوارهٔ نخستین ضخیم‌شده، نگهداری اندام‌های در حال رشد را ممکن می‌کند.'),
('تخصص‌یافتگی انحصاری برای انتقال پیام عصبی','در گیاه بافت عصبی به شکل جانوری وجود ندارد؛ کلانشیم بافت نگهدارنده است.')],2,'زنده‌بودن و نوع دیواره در انتخاب بافت نگهدارنده مهم‌اند.')
mcq(10,6,'مریستم و رشد','با حذف دقیق جوانهٔ انتهایی یک ساقه، رشد طولی همان رأس مختل می‌شود. کدام توضیح ساختاری درست‌تر است؟',[
('بخشی از یاخته‌های دارای توان تقسیم در مریستم رأسی حذف شده‌اند','مریستم رأسی با تولید یاخته‌های جدید در رشد نخستین و افزایش طول نقش دارد.'),
('فقط فعالیت مریستم جانبیِ افزایندهٔ قطر حذف شده است','جوانهٔ انتهایی دارای مریستم رأسیِ مؤثر در رشد طولی است؛ مریستم جانبی عمدتاً به افزایش قطر مربوط است.'),
('رشد طولی فقط با بزرگ‌شدن یاخته‌های کاملاً بالغ و بدون تولید یاخته ادامه داشته است','تولید یاخته در مریستم رأسی نیز در رشد نخستین نقش دارد و حذف آن رشد رأس را مختل می‌کند.'),
('با حذف رأس، تعداد تقسیم‌ها در همان رأس الزاماً بیشتر می‌شود','برداشتن بافت تقسیم‌شونده افزایش تقسیم در همان بافت حذف‌شده را ایجاد نمی‌کند؛ رشد جانبی موضوع متفاوتی است.')],0,'نقطهٔ رشد را با بافت بالغ و نقش مریستم جانبی اشتباه نگیریم.')
mcq(10,6,'دیواره و ارتباط یاخته‌ای','دو یاختهٔ گیاهی مجاور می‌توانند از راه پلاسمودسم‌ها مواد را مبادله کنند. کدام نتیجه درست است؟',[
('وجود دیواره هر نوع ارتباط میان سیتوپلاسم‌ها را ناممکن می‌کند','پلاسمودسم‌ها راه ارتباطی از میان دیواره فراهم می‌کنند.'),
('پلاسمودسم همان روزنهٔ سطح برگ است','روزنه ساختاری در روپوست برای تبادل با محیط است؛ پلاسمودسم ارتباط میان یاخته‌های مجاور است.'),
('وجود پلاسمودسم به معنی حذف کامل دیوارهٔ مشترک است','راه‌های باریک ارتباطی در دیواره وجود دارند؛ کل دیواره حذف نمی‌شود.'),
('دیوارهٔ جداکننده می‌تواند دارای راه‌های ارتباط سیتوپلاسمی باشد','پلاسمودسم‌ها پیوستگی ارتباطی سیتوپلاسم یاخته‌های مجاور را از میان دیواره برقرار می‌کنند.')],3,'یک سد ساختمانی می‌تواند راه‌های ارتباطی تخصص‌یافته داشته باشد.')

mcq(10,7,'تعرق و انتقال شیرهٔ خام','در روزی خشک، تعرق برگ افزایش یافته و آب کافی در خاک هست. چه عاملی مستقیماً به کشیده‌شدن ستون آب در آوند چوبی کمک می‌کند؟',[
('افزایش فشار در برگ بر اثر خروج بخار آب','خروج آب از برگ کشش و کاهش فشار مؤثر ایجاد می‌کند، نه افزایش فشاری که ستون آب را به پایین براند.'),
('کاهش فشار در برگ همراه هم‌چسبی مولکول‌های آب','تبخیر آب از برگ کشش ایجاد می‌کند و هم‌چسبی آب پیوستگی ستون آب را در انتقال حفظ می‌کند.'),
('انقباض منظم یاخته‌های مردهٔ آوند مانند قلب','عناصر رسانای چوبی هنگام بلوغ معمولاً مرده‌اند و مانند قلب منقبض نمی‌شوند.'),
('جابجایی آب فقط از راه آوند آبکش از برگ به ریشه','مسیر عمدهٔ صعود آب شیرهٔ خام آوند چوبی است، نه انحصاراً آبکش از برگ به ریشه.')],1,'صعود آب را با تلمبهٔ ماهیچه‌ای یا انتقال قند یکی ندانیم.')
mcq(10,7,'منبع و مخزن','برگی بالغ قند تولید می‌کند و میوهٔ در حال رشد آن را مصرف یا ذخیره می‌کند. دربارهٔ انتقال شیرهٔ پرورده کدام درست است؟',[
('میوه منبع و برگ بالغ مخزن این انتقال است','در وضعیت گفته‌شده، برگ صادرکننده و منبع است و میوه گیرنده و مخزن.'),
('هر مخزن باید حتماً پایین‌تر از منبع باشد','نقش منبع و مخزن بر تولید و مصرف یا ذخیره استوار است و به بالا یا پایین‌بودن محدود نیست.'),
('قند با آبکش از منبعِ برگ به مخزنِ میوه می‌رود','شیرهٔ پرورده مواد آلی را از منبع به مخزن می‌برد؛ جهت نسبت به زمین معیار تعیین مسیر نیست.'),
('قندها فقط از یاخته‌های مردهٔ آوند چوبی عبور می‌کنند','انتقال عمدهٔ شیرهٔ پرورده به آوند آبکش مربوط است؛ آوند چوبی عمدتاً آب و یون‌ها را جابه‌جا می‌کند.')],2,'جهت منبع به مخزن را با جهت ثابت بالا یا پایین اشتباه نگیریم.')
mcq(10,7,'جذب آب از خاک','به خاک یک گیاه، مقدار زیادی نمک افزوده می‌شود و گیاه با وجود مرطوب‌بودن خاک پژمرده می‌شود. توضیح مناسب‌تر چیست؟',[
('شوری زیاد، شرایط اسمزی را برای جذب آب نامساعد می‌کند','جذب آب به اختلاف شرایط اسمزی وابسته است؛ خاک مرطوبِ بسیار شور الزاماً آب را در اختیار یاخته‌های ریشه قرار نمی‌دهد.'),
('هرچه نمک بیشتر شود، ورود آب بدون محدودیت بیشتر می‌شود','افزایش شدید غلظت بیرونی می‌تواند جهت یا شدت جریان اسمزی را بر خلاف جذب تغییر دهد.'),
('پژمردگی نشان می‌دهد هیچ مولکول آبی در خاک نمانده است','وجود آب فیزیکی در خاک با امکان جذب آن یکسان نیست.'),
('نمک فقط بر گرده‌افشانی اثر دارد و به ریشه مربوط نیست','یون‌ها و غلظت محلول خاک بر جذب آب در ریشه اثر می‌گذارند.')],0,'مرطوب‌بودن خاک به‌تنهایی برای جذب آب کافی نیست.')
mcq(10,7,'مسیرهای عبور از ریشه','آب در پوست ریشه از مسیر دیواره‌ای پیش می‌رود و به درون‌پوست می‌رسد. وجود نوار کاسپاری چه اثری دارد؟',[
('جلوگیری از ورود آب به همهٔ یاخته‌های ریشه در هر شرایط','نوار کاسپاری همهٔ راه‌های ورود آب به ریشه را مسدود نمی‌کند.'),
('حذف نقش غشای درون‌پوست در گزینش یون‌ها','نوار کاسپاری با بستن مسیر دیواره‌ای، نقش عبور غشایی و گزینش را برجسته می‌کند، نه حذف.'),
('بازگذاشتن کامل مسیر دیواره‌ای تا درون آوند بدون عبور از غشا','نوار کاسپاری مسیر دیواره‌ای را در درون‌پوست مسدود می‌کند.'),
('واداشتن این جریان به عبور از غشای درون‌پوست','سد نوار کاسپاری سبب می‌شود آب و مواد مسیر دیواره‌ای برای رسیدن به استوانهٔ آوندی از غشا عبور کنند و امکان گزینش ایجاد شود.')],3,'سد دیواره‌ای با توقف همهٔ جذب‌ها متفاوت است.','hard')
